package limiter

import "sync"

type Counter struct {
	limit   int
	current int
	mu      sync.Mutex
}

func New(limit int) *Counter {
	return &Counter{limit: limit, current: 0}
}

func (c *Counter) Allow() bool {
	c.mu.Lock()
	defer c.mu.Unlock()
	if c.current < c.limit {
		c.current++
		return true
	}
	return false
}

